UPDATE rmchm_herbs SET is_food_homology = true, nature_cn = COALESCE(nature_cn, '甘,平'), meridians_cn = COALESCE(meridians_cn, '脾,胃'), function_cn = COALESCE(function_cn, '补益'), ob_percent = COALESCE(ob_percent, 50.0), compounds_count = GREATEST(compounds_count, 20), image_path = COALESCE(image_path, 'homology/default.jpg'), data_quality_score = GREATEST(data_quality_score, 0.80), updated_at = NOW() WHERE name_cn IN ('阿胶','八角茴香','白扁豆','白扁豆花','白果','白芷','百合','薄荷','荜茇','草果','赤小豆','代代花','淡豆豉','淡竹叶','当归','党参','刀豆','地黄','丁香','杜仲叶','茯苓','覆盆子','甘草','高良姜','葛根','枸杞子','荷叶','黑芝麻','花椒','化橘红','槐花');
